  公务员理财: 'mechanism',
  买房: 'mechanism',
  卖房: 'mechanism',
  涨薪: 'mechanism',
  美国政治: 'concept',
  商学院: 'concept',
  二代企业: 'concept',
  大学生: 'concept',
  唇腭裂: 'concept',
  校长: 'concept',
